mapper.select:
select r.id, r.season_id as seasonId, r.stage_id as stageId, r.rank_type as rankType, r.team_id as teamId, t.team_no as teamNo, t.team_name as teamName, t.short_name as shortName, lf.access_url as logoUrl, r.rank_no as rankNo, r.previous_rank as previousRank, case when r.previous_rank is null then null else (r.previous_rank - r.rank_no) end as rankChange, r.stat_value as statValue, s.games as games, r.snapshot_date as snapshotDate from basket_team_rank r left join basket_team t on t.id = r.team_id and t.is_delete = 0 left join basket_file_asset lf on lf.id = t.logo_file_id and lf.is_delete = 0 left join basket_team_season_stat s on s.season_id = r.season_id and s.stage_id = r.stage_id and s.team_id = r.team_id and s.is_delete = 0 where r.is_delete = 0 and r.snapshot_date = ( select max(r2.snapshot_date) from basket_team_rank r2 where r2.is_delete = 0 and r2.season_id = r.season_id and r2.stage_id = r.stage_id and r2.rank_type = r.rank_type ) and r.season_id = #{seasonId} and r.stage_id = #{stageId} and r.rank_type = #{rankType} and r.team_id = #{teamId}
and (t.team_name like concat('%', #{keyword}, '%') or t.short_name like concat('%', #{keyword}, '%'))
order by r.rank_no, r.team_id

mapper.delete:
delete from basket_team_rank
where season_id = #{seasonId}
  and stage_id = #{stageId} and snapshot_date = #{snapshotDate}

mapper.select:
select rank_no from basket_team_rank
where is_delete = 0 and season_id = #{seasonId} and stage_id = #{stageId}
  and rank_type = #{rankType} and team_id = #{teamId}
  and snapshot_date < #{beforeDate}
order by snapshot_date desc
limit 1
